// Install: npm install @aws-sdk/client-s3 @aws-sdk/client-dynamodb

import { S3Client, PutObjectCommand, GetObjectCommand } from '@aws-sdk/client-s3';

// SDK automatically finds credentials in order:
// 1. Environment variables (AWS_ACCESS_KEY_ID, etc.)
// 2. ~/.aws/credentials file
// 3. EC2/ECS/Lambda IAM role (preferred for production)
const s3 = new S3Client({ region: 'ap-south-1' });

// Upload a file
async function uploadFile(bucket: string, key: string, body: Buffer) {
  await s3.send(new PutObjectCommand({
    Bucket: bucket,
    Key: key,
    Body: body,
    ContentType: 'application/octet-stream',
  }));
  console.log(`Uploaded s3://${bucket}/${key}`);
}

// Download a file
async function downloadFile(bucket: string, key: string): Promise<string> {
  const response = await s3.send(new GetObjectCommand({ Bucket: bucket, Key: key }));
  return await response.Body!.transformToString();
}

// Generate a pre-signed URL (time-limited download link)
import { getSignedUrl } from '@aws-sdk/s3-request-presigner';
async function getDownloadUrl(bucket: string, key: string): Promise<string> {
  return getSignedUrl(
    s3,
    new GetObjectCommand({ Bucket: bucket, Key: key }),
    { expiresIn: 3600 }  // 1 hour
  );
}
